    const line = id.slice(0, 2), Ln = LINE[line], rig = 'of_' + id, k = 1 + 0.8 * (grade - 1);
    const b1 = scale(Ln.bonus, grade), b2 = scale(Ln.bonus, 2 * grade);
    const set = { id, line, grade, name, lv, items: {}, acc: 'acc_' + rig, bonus: [b1, b2] };
